// Last resort when all three AI providers failed: deterministic score so the lead is NEVER lost.
const base = $('Build AI Prompt').first().json;
const errs = ['Parse Groq', 'Parse OpenRouter', 'Parse Gemini'].map(n => { try { return `${n}: ${$(n).first().json.ai_error}`; } catch (e) { return ''; } }).filter(Boolean).join(' | ');
const s = base.rule_score;
const cat = s >= 75 ? 'hot' : s >= 50 ? 'warm' : 'cold';
return [{ json: { ...base, ai_ok: false, ai_provider: 'rule_based_fallback', ai_model: '', ai_error: errs.slice(0, 500), ai: {
  intent: base.signals.spam_suspected ? 'spam' : (s >= 75 ? 'purchase_ready' : s >= 50 ? 'evaluating' : 'researching'),
  qualification: cat, score: s, qualified: s >= 60,
  reason: 'AI providers unavailable; scored with deterministic rules (budget, authority, urgency, need, detail).',
  key_signals: [], risk_flags: ['ai_unavailable'],
  recommended_action: 'human_review', confidence: 0.3,
  follow_up_email_subject: '', follow_up_email_body: '',
}}}];

// ===== Deterministic business rules live HERE, not in the prompt =====
const HOT = 75, WARM = 50, QUALIFIED_MIN = 60;
const REVIEW_BAND = [55, 65];       // borderline scores go to a human
const MIN_CONFIDENCE = 0.6;
const MAX_AI_RULE_GAP = 35;         // AI and rules disagree a lot -> human review
const SPAM_CAP = 10;
// =====================================================================

const d = $input.first().json;
const ai = d.ai;
const usedAi = d.ai_ok === true;

let ai_score = ai.score;
let final_score = usedAi ? Math.round(0.7 * ai.score + 0.3 * d.rule_score) : d.rule_score;

const spam = ai.intent === 'spam' || d.signals.spam_suspected;
if (spam) final_score = Math.min(final_score, SPAM_CAP);

const qualification = final_score >= HOT ? 'hot' : final_score >= WARM ? 'warm' : 'cold';
const qualified = !spam && final_score >= QUALIFIED_MIN;

const review_reasons = [];
if (!usedAi) review_reasons.push('ai_unavailable');
if (usedAi && ai.confidence < MIN_CONFIDENCE) review_reasons.push('low_confidence');
if (usedAi && Math.abs(ai.score - d.rule_score) > MAX_AI_RULE_GAP) review_reasons.push('ai_vs_rules_disagree');
if (!spam && final_score >= REVIEW_BAND[0] && final_score <= REVIEW_BAND[1]) review_reasons.push('borderline_score');
if (spam && ai.intent !== 'spam') review_reasons.push('rules_flagged_spam');
const needs_review = review_reasons.length > 0;

let recommended_action, crm_status;
if (spam) { recommended_action = 'discard'; crm_status = 'spam'; }
else if (needs_review) { recommended_action = 'human_review'; crm_status = 'needs_review'; }
else if (qualification === 'hot') { recommended_action = 'immediate_sales_call'; crm_status = 'new_hot'; }
else if (qualification === 'warm') { recommended_action = 'sales_follow_up_email'; crm_status = 'new_warm'; }
else { recommended_action = ai.recommended_action === 'send_resources' ? 'send_resources' : 'nurture_sequence'; crm_status = 'new_cold'; }

const reason = spam
  ? `Flagged as spam. ${ai.reason}`.trim()
  : ai.reason + (needs_review ? ` (Review: ${review_reasons.join(', ')})` : '');

const row = {
  lead_id: d.lead_id, received_at: d.received_at, name: d.name, email: d.email, company: d.company, role: d.role,
  phone: d.phone, budget_text: d.budget_text, budget_usd: d.budget_usd, timeline: d.timeline, message: d.message, source: d.source,
  intent: ai.intent, qualification, qualified: qualified ? 'TRUE' : 'FALSE', score: final_score, ai_score, rule_score: d.rule_score,
  confidence: ai.confidence, reason, key_signals: ai.key_signals.join('; '), risk_flags: [...ai.risk_flags, ...review_reasons].join('; '),
  recommended_action, ai_recommended_action: ai.recommended_action, crm_status, needs_review: needs_review ? 'TRUE' : 'FALSE',
  ai_provider: d.ai_provider, ai_model: d.ai_model || '', ai_error: d.ai_error || '',
  follow_up_subject: ai.follow_up_email_subject, follow_up_body: ai.follow_up_email_body, last_updated: new Date().toISOString(),
};

const response = {
  status: 'processed', lead_id: d.lead_id, qualified, qualification, score: final_score, intent: ai.intent,
  reason, recommended_action, crm_status, needs_review, review_reasons, ai_provider: d.ai_provider,
};

const alert_required = !spam && (qualification === 'hot' || needs_review);
const alert_subject = `[${needs_review ? 'REVIEW' : 'HOT LEAD'}] ${d.name}${d.company ? ' @ ' + d.company : ''} - score ${final_score}`;
const alert_body = [
  `Lead: ${d.name} <${d.email}>`, `Company: ${d.company || '-'}   Role: ${d.role || '-'}`,
  `Budget: ${d.budget_text || '-'}   Timeline: ${d.timeline || '-'}`, '',
  `Category: ${qualification.toUpperCase()}  Score: ${final_score}  Qualified: ${qualified}`,
  `Intent: ${ai.intent}   Next action: ${recommended_action}`, `Why: ${reason}`, '',
  `Message: ${d.message}`, '', 'A follow-up DRAFT is stored in the CRM sheet (follow_up_subject / follow_up_body). Nothing was sent to the lead.',
].join('\n');

return [{ json: { row, response, alert_required, alert_subject, alert_body } }];
